-- RRC059: MariaDB10.11, dedicated fresh admin session; manual coordinated application only.
-- Source recipe facts/provenance: batch.public.json. No engine/updater/version/rule changes.
-- Anonymous compound block: no permanent helper procedure or migration table.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE already_present INT DEFAULT 0;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 requires fresh transaction-free session'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 strict SQL mode required'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tradeskill_recipe','tradeskill_recipe_entries','items') AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc059_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc059_parents LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc059_parent_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc059_books(item_id INT PRIMARY KEY,filename VARCHAR(100),book_id INT,text_sha256 CHAR(64),language INT);
 CREATE TEMPORARY TABLE rrc059_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc059_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 START TRANSACTION;
 SET own_transaction=TRUE;
 IF EXISTS(SELECT 1 FROM rrc059_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 HalfBar parent drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc059_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc059_parents p ON p.id=r.recipe_id)<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 HalfBar entries drift'; END IF;
 IF (SELECT COUNT(*) FROM rrc059_books e JOIN items i ON i.id=e.item_id JOIN books b ON b.id=e.book_id WHERE i.itemclass=2 AND BINARY i.filename=BINARY e.filename AND BINARY b.name=BINARY e.filename AND BINARY SHA2(b.txtfile,256)=BINARY e.text_sha256 AND b.language=e.language)<>8 OR (SELECT COUNT(*) FROM books b JOIN rrc059_books e ON b.name=CONVERT(e.filename USING latin1) COLLATE latin1_swedish_ci)<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 native book name/text dependency mismatch'; END IF;
 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO already_present FROM tradeskill_recipe r JOIN rrc059_recipes e ON r.id=e.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rrc059_items e LEFT JOIN items i ON i.id=e.id WHERE i.id IS NULL OR BINARY i.Name<>BINARY e.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 item identity/dependency mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE itemclass=1 AND ((id=17877 AND bagtype=10 AND bagslots=10) OR(id IN(17902,17276) AND bagtype=10 AND bagslots=8) OR(id=17911 AND bagtype=19 AND bagslots=10) OR(id=17912 AND bagtype=20 AND bagslots=4) OR(id IN(17764,17187,62480) AND bagtype=20 AND bagslots=6)))<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 native container mismatch'; END IF;
 IF already_present NOT IN (0,42) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 partial batch or ID collision'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe r JOIN rrc059_recipes e ON r.tradeskill=e.tradeskill AND r.name=e.name WHERE r.id<>e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 existing recipe-name collision'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc059_entries e ON r.item_id=e.item_id JOIN rrc059_recipes q ON e.recipe_id=q.id WHERE e.successcount>0 AND e.componentcount=0 AND e.iscontainer=0 AND r.successcount>r.componentcount AND r.iscontainer=0 AND r.recipe_id<>e.recipe_id AND NOT((e.item_id=36449 AND e.recipe_id IN (3093566) AND r.recipe_id IN (3093107)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 existing output recipe collision'; END IF;
 IF already_present=0 THEN
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc059_recipes e ON r.recipe_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 orphan target entries collision'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM rrc059_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 recipe postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc059_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 expected entry absent'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc059_recipes q ON q.id=r.recipe_id LEFT JOIN rrc059_entries e ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 foreign/different target entries'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc059_recipes q ON q.id=r.recipe_id)<>400 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 target entry multiplicity mismatch'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before+IF(already_present=0,42,0) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before+IF(already_present=0,400,0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 unexpected table row-count delta'; END IF;
 IF EXISTS(SELECT 1 FROM rrc059_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 HalfBar parent drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc059_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc059_parents p ON p.id=r.recipe_id)<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 HalfBar entries drift'; END IF;
 IF (SELECT COUNT(*) FROM rrc059_books e JOIN items i ON i.id=e.item_id JOIN books b ON b.id=e.book_id WHERE i.itemclass=2 AND BINARY i.filename=BINARY e.filename AND BINARY b.name=BINARY e.filename AND BINARY SHA2(b.txtfile,256)=BINARY e.text_sha256 AND b.language=e.language)<>8 OR (SELECT COUNT(*) FROM books b JOIN rrc059_books e ON b.name=CONVERT(e.filename USING latin1) COLLATE latin1_swedish_ci)<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC059 native book name/text dependency mismatch'; END IF;
 DROP TEMPORARY TABLE rrc059_parents;
 DROP TEMPORARY TABLE rrc059_parent_entries;
 DROP TEMPORARY TABLE rrc059_books;
 DROP TEMPORARY TABLE rrc059_entries;
 DROP TEMPORARY TABLE rrc059_recipes;
 DROP TEMPORARY TABLE rrc059_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC059' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
